def language_note(language, english):
    if not isinstance(language, str) or not language.strip():
        return ('Определи исходный язык по тексту и контексту, включая смешанные реплики. '
                'Для неправильных глаголов восстанови лемму и грамматическую форму. '
                'Сохрани вид, наклонение, источник сведений, вежливость и то, кто совершает действие. '
                'Не достраивай пропущенное без опоры на контекст. Правила английского применяй только к английскому: ' + english)
    key = language.strip().lower().replace('_', '-').split('-', 1)[0]
    if key == 'en':
        return english
    return PROFILES.get(key, 'Учитывай грамматику и неправильные формы исходного языка; не применяй к нему правила английского.')
